#!/usr/bin/env node
// Generates ui/src/tokens/tokens.css and ui/src/tokens/tokens.ts from design-system/tokens.json.
// design-system/tokens.json stays the single source of truth; never edit the generated files.
//
//   node ui/scripts/build-tokens.mjs           write both files
//   node ui/scripts/build-tokens.mjs --check   exit 1 if either file is stale (use in CI)
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, '..', '..', 'design-system', 'tokens.json');
const outDir = join(here, '..', 'src', 'tokens');
const t = JSON.parse(readFileSync(src, 'utf8'));

const themes = t.color.themes.map((x) => x.id);
const first = themes[0];
const raw = (tok, theme) =>
  typeof tok.value === 'string' ? tok.value : (tok.value[theme] ?? tok.value[first]);
const cssVal = (v) => v.replace(/^\{(.+)\}$/, 'var(--$1)');
const resolve = (v, theme, seen = 0) => {
  const m = /^\{(.+)\}$/.exec(v);
  if (!m || seen > 16) {
    return v;
  }
  const target = t.color.tokens.find((x) => x.name === m[1]);
  return target ? resolve(raw(target, theme), theme, seen + 1) : v;
};
const camel = (s) => s.replace(/[-.]([a-z0-9])/g, (_, c) => c.toUpperCase());
const px = (v) => (typeof v === 'number' ? `${v}px` : v);

// ---------- tokens.css ----------
const themeBlock = (theme) =>
  [
    ...t.color.tokens.map((x) => `  --${x.name}: ${cssVal(raw(x, theme))};`),
    ...(t.shadow?.tokens ?? []).map((x) => `  --${x.name}: ${cssVal(raw(x, theme))};`),
  ].join('\n');
const plain = ['spacing', 'radius', 'size'].flatMap((f) =>
  (t[f]?.tokens ?? []).map((x) => `  --${x.name}: ${x.value};`),
);
const presetVariables = Object.entries(t.brandPresets ?? {}).flatMap(([role, presets]) =>
  presets.map((p) => `  --preset-${role}-${p.id}: ${p.value};`),
);
const presetClasses = Object.entries(t.brandPresets ?? {}).flatMap(([role, presets]) =>
  presets.map(
    (p) => `.brand-preset-${role}-${p.id} { background: var(--preset-${role}-${p.id}); }`,
  ),
);
const fonts = Object.entries(t.type.families).map(([k, v]) => `  --font-${k}: ${v};`);
const styles = t.type.groups.flatMap((g) =>
  g.styles.map((s) => ({ ...s, family: s.family ?? g.family, group: g.name })),
);
const typeClasses = styles.map(
  (s) =>
    `.ds-${s.name} { ${[
      `font-family: var(--font-${s.family})`,
      `font-size: ${px(s.fontSize)}`,
      s.lineHeight && `line-height: ${s.lineHeight}`,
      s.fontWeight && `font-weight: ${s.fontWeight}`,
      s.fontStyle && `font-style: ${s.fontStyle}`,
      s.letterSpacing && `letter-spacing: ${s.letterSpacing}`,
    ]
      .filter(Boolean)
      .join('; ')}; }`,
);
const dark = themes.includes('dark') ? 'dark' : null;

const css = `/* ${t.name} — generated by ui/scripts/build-tokens.mjs from design-system/tokens.json. Do not edit. */

:root, [data-theme="${first}"] {
${themeBlock(first)}
  color-scheme: ${first};
}
${themes
  .slice(1)
  .map((th) => `[data-theme="${th}"] {\n${themeBlock(th)}\n  color-scheme: ${th};\n}`)
  .join('\n')}
${dark ? `@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="${first}"]) {\n${themeBlock(dark).replace(/^/gm, '  ')}\n    color-scheme: dark;\n  }\n}\n` : ''}
:root {
${[...plain, ...fonts, ...presetVariables].join('\n')}
}

${presetClasses.join('\n')}
${typeClasses.join('\n')}
`;

// ---------- tokens.ts ----------
const colorNames = t.color.tokens.map((x) => x.name);
const colors = Object.fromEntries(
  themes.map((th) => [
    th,
    Object.fromEntries(t.color.tokens.map((x) => [x.name, resolve(raw(x, th), th)])),
  ]),
);
const shadows = Object.fromEntries(
  themes.map((th) => [
    th,
    Object.fromEntries((t.shadow?.tokens ?? []).map((x) => [x.name, raw(x, th)])),
  ]),
);
const list = (f) => Object.fromEntries((t[f]?.tokens ?? []).map((x) => [camel(x.name), x.value]));
const typeStyles = Object.fromEntries(
  styles.map((s) => [
    camel(s.name),
    {
      className: `ds-${s.name}`,
      fontFamily: `var(--font-${s.family})`,
      fontSize: px(s.fontSize),
      ...(s.lineHeight ? { lineHeight: String(s.lineHeight) } : {}),
      ...(s.fontWeight ? { fontWeight: s.fontWeight } : {}),
      ...(s.fontStyle ? { fontStyle: s.fontStyle } : {}),
      ...(s.letterSpacing ? { letterSpacing: s.letterSpacing } : {}),
    },
  ]),
);
const J = (o) => JSON.stringify(o, null, 2);
const ts = `// ${t.name} — generated by ui/scripts/build-tokens.mjs from design-system/tokens.json. Do not edit.
/* eslint-disable */

export const themes = ${J(themes)} as const;
export type ThemeName = (typeof themes)[number];

export type ColorToken = ${colorNames.map((n) => `'${n}'`).join(' | ')};

/** Resolved hex values per theme, for JS (charts, canvas, meta theme-color). In CSS, use cssVar(). */
export const colors: Record<ThemeName, Record<ColorToken, string>> = ${J(colors)};

export const brandPresets = ${J(t.brandPresets ?? {})} as const;

export const shadows = ${J(shadows)} as const;

export const spacing = ${J(list('spacing'))} as const;
export const radius = ${J(list('radius'))} as const;
export const size = ${J(list('size'))} as const;

export const fontFamilies = ${J(t.type.families)} as const;

/** Text styles. Use the className (from tokens.css) or spread the style object. */
export const typography = ${J(typeStyles)} as const;
export type TypeStyle = keyof typeof typography;

/** Every token is also a CSS custom property: cssVar('majorelle') → 'var(--majorelle)'. */
export const cssVar = (name: ColorToken | 'shadow-pop' | \`space-\${number}\` | \`radius-\${string}\` | 'measure' | 'shell' | 'target' | \`font-\${keyof typeof fontFamilies}\`) => \`var(--\${name})\`;
`;

const files = [
  [join(outDir, 'tokens.css'), css],
  [join(outDir, 'tokens.ts'), ts],
];
if (process.argv.includes('--check')) {
  const stale = files.filter(([f, c]) => !existsSync(f) || readFileSync(f, 'utf8') !== c);
  if (stale.length) {
    console.error(
      'Stale: ' + stale.map(([f]) => f).join(', ') + '\nRun: node ui/scripts/build-tokens.mjs',
    );
    process.exit(1);
  }
  console.log('ui tokens are up to date.');
} else {
  files.forEach(([f, c]) => writeFileSync(f, c));
  console.log('Wrote ' + files.map(([f]) => f).join(', '));
}
